if(EditorApplication.isPlaying)throw new System.Exception("Edit only");string D="ArtSource/Pipeline/Review/BriarwickEnvironment07";if(System.IO.File.Exists(D+"/TrailIntegration.json"))throw new System.Exception("Already refined");var td=Terrain.activeTerrain.terrainData;var route=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("ArtSource/Pipeline/Review/BriarwickWoodland03/Integration.json"))["route"].Select(p=>new Vector2((float)p["x"],(float)p["z"])).Skip(2).ToArray();var alpha=td.GetAlphamaps(0,0,1024,1024);int changed=0;for(int z=0;z<1024;z++)for(int x=0;x<1024;x++){var p=new Vector2(-160+x*320f/1023,-170+z*320f/1023);if(p.y<94||p.y>132||p.x< -33||p.x> -19)continue;float d=999;for(int i=0;i<route.Length-1;i++){var delta=route[i+1]-route[i];float t=Mathf.Clamp01(Vector2.Dot(p-route[i],delta)/delta.sqrMagnitude);d=Mathf.Min(d,Vector2.Distance(p,route[i]+delta*t));}float n=Mathf.PerlinNoise(p.x*.5f+21,p.y*.5f+37);float radius=Mathf.Lerp(2.2f,1.1f,Mathf.SmoothStep(0,1,Mathf.InverseLerp(95,103,p.y)));float strength=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(radius*.38f,radius+.35f+(n-.5f)*.3f,d)))*(.48f+.12f*n);if(strength<.001f)continue;for(int l=0;l<8;l++)alpha[z,x,l]*=1-strength;alpha[z,x,7]+=strength;changed++;}td.SetAlphamaps(0,0,alpha);td.SetBaseMapDirty();Terrain.activeTerrain.Flush();EditorUtility.SetDirty(td);AssetDatabase.SaveAssetIfDirty(td);var result=new{source="Existing Woodland03 recorded route; not a new alignment",points=route.Select(p=>new[]{p.x,p.y}).ToArray(),length=Enumerable.Range(0,route.Length-1).Sum(i=>Vector2.Distance(route[i],route[i+1])),changedTexels=changed,additionalGeometry=0,additionalColliders=0,vegetationChanges=0};System.IO.File.WriteAllText(D+"/TrailIntegration.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
